<script lang="ts">
  import { liveValue } from './live-value';
  import type { Control } from './forms';
  let { control, labelledby }: { control: Control; labelledby?: string } = $props();
  // a field without its own name is named by its row's caption
  const named = (attrs: Record<string, unknown> | undefined) => !!attrs && (attrs['aria-label'] != null || attrs['aria-labelledby'] != null);
</script>
{#if control.kind === 'input'}{#key control.attrs.type}{#if control.attrs.type === 'checkbox'}<input {...control.attrs} aria-labelledby={named(control.attrs) ? undefined : labelledby} checked={control.checked}>{:else}<input {...control.attrs} aria-labelledby={named(control.attrs) ? undefined : labelledby} {@attach liveValue(control.value)}>{/if}{/key}{:else if control.kind === 'select'}<select {...control.attrs} aria-labelledby={named(control.attrs) ? undefined : labelledby} {@attach liveValue(control.value, control.options)}>{#each control.options as [value, label]}<option {value}>{label}</option>{/each}</select>{:else if control.kind === 'colour'}<button type="button" class="cbtn" data-sercolor={control.index} title={control.value}><span style:background={control.css}></span></button>{:else if control.kind === 'fillColour'}<button type="button" class={'cbtn' + (control.none ? ' none' : '')} {...control.attrs}><span style:background={control.css}></span></button><span class="cval">{control.label}</span>{:else if control.kind === 'angle'}<input type="range" {...control.attrs} aria-labelledby={named(control.attrs) ? undefined : labelledby} {@attach liveValue(control.value)}><label class="ang" title="Click to type a value"><input type="number" {...control.numericAttrs} aria-labelledby={named(control.numericAttrs) ? undefined : labelledby} {@attach liveValue(control.numericValue)}>{control.unit}</label>{:else if control.kind === 'button'}<button {...control.attrs}>{#if control.swatch}<i style:background={control.swatch.css} class={control.swatch.none ? 'none' : undefined}></i>{/if}{#if control.svg}{@html control.svg}{/if}{control.text}</button>{:else if control.kind === 'spacer'}<div class="spacer"></div>{:else if control.kind === 'code'}<code class={control.class}>{control.text}</code>{:else if control.kind === 'texColour'}<button type="button" class={'cbtn' + (control.none ? ' none' : '')} data-tc={control.nullable ? 'n' : ''} title={control.title} data-dl={control.defaultLabel} data-dsw={control.defaultSwatch}><span style:background={control.css}></span></button><span class="cval">{control.label}</span><input type="hidden" {...control.attrs} {@attach liveValue(control.value)}>{:else}<span class={control.class}>{control.text}</span>{/if}
